// The Settings screen.
//
// Renders itself FROM the schema in settings.js rather than from markup, so
// the three sections and every control in them are generated by walking one
// table. That is what keeps "all three sections are reachable from every
// entry point" true by construction: the tab bar is built from SECTIONS
// unconditionally, and the entry point only chooses which tab starts
// selected. There is no code path in which an entry point can produce a
// screen with a section missing from it.
//
// Rendering is deliberately full-redraw-per-section rather than
// incremental. A section is at most a dozen controls, it is rebuilt only on
// a tab change or a value change, and a phone does that in well under a
// frame -- so the complexity of patching individual nodes would buy
// nothing and cost the guarantee that what is on screen matches the store.

import {
  SCHEMA, SECTIONS, APP_VERSION,
  getSetting, setSetting, resetSettings, subscribeSettings,
} from './settings.js';
import { clearAllData } from './storage.js';
import { transitionHidden, playEnter } from './transitions.js';

const els = {};
let activeSection = 'main';
// Where Settings was opened from, so Back returns there rather than always
// dumping the user on Home. Holds the element to go back to, plus an
// optional callback for anything that screen needs done on the way in.
let origin = null;
let onToast = () => {};

function field(entry) {
  const wrap = document.createElement('div');
  wrap.className = 'settings-field';
  wrap.dataset.key = entry.key;

  const label = document.createElement('span');
  label.className = 'settings-field__label';
  label.textContent = entry.label;
  wrap.appendChild(label);

  if (entry.hint) {
    const hint = document.createElement('p');
    hint.className = 'settings-field__hint';
    hint.textContent = entry.hint;
    wrap.appendChild(hint);
  }

  const row = document.createElement('div');
  row.className = 'settings-field__row';
  wrap.appendChild(row);

  const current = getSetting(entry.key);

  if (entry.kind === 'toggle') {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'toggle-chip';
    button.id = `set-${entry.key}`;
    button.setAttribute('aria-pressed', String(Boolean(current)));
    button.textContent = current ? 'On' : 'Off';
    button.addEventListener('click', () => setSetting(entry.key, !getSetting(entry.key)));
    row.appendChild(button);
    return wrap;
  }

  if (entry.kind === 'choice') {
    for (const option of entry.options) {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'settings-choice';
      // Indexed rather than named by value, because a value can be a
      // boolean or a number and an id has to be a string either way.
      button.dataset.value = String(option.value);
      button.id = `set-${entry.key}-${String(option.value)}`;
      button.setAttribute('aria-pressed', String(option.value === current));
      button.textContent = option.label;
      if (option.note) {
        const note = document.createElement('span');
        note.className = 'settings-choice__note';
        note.textContent = option.note;
        button.appendChild(note);
      }
      button.addEventListener('click', () => setSetting(entry.key, option.value));
      row.appendChild(button);
    }
    return wrap;
  }

  if (entry.kind === 'slider') {
    const input = document.createElement('input');
    input.type = 'range';
    input.className = 'slider';
    input.id = `set-${entry.key}`;
    input.min = String(entry.min);
    input.max = String(entry.max);
    input.step = String(entry.step);
    input.value = String(current);
    const value = document.createElement('span');
    value.className = 'settings-field__value';
    value.textContent = entry.format ? entry.format(current) : String(current);
    input.addEventListener('input', () => {
      const next = Number(input.value);
      // The readout is updated here rather than waiting for the store's
      // notify, so dragging stays smooth even though every step writes.
      value.textContent = entry.format ? entry.format(next) : String(next);
      setSetting(entry.key, next);
    });
    row.appendChild(input);
    row.appendChild(value);
    return wrap;
  }

  if (entry.kind === 'color') {
    const input = document.createElement('input');
    input.type = 'color';
    input.id = `set-${entry.key}`;
    input.value = String(current);
    input.addEventListener('input', () => setSetting(entry.key, input.value));
    const readout = document.createElement('span');
    readout.className = 'settings-field__value';
    readout.textContent = String(current).toUpperCase();
    input.addEventListener('input', () => { readout.textContent = input.value.toUpperCase(); });
    row.appendChild(input);
    row.appendChild(readout);
    return wrap;
  }

  return wrap;
}

function groupTitle(text) {
  const h = document.createElement('p');
  h.className = 'settings-group-title';
  h.textContent = text;
  return h;
}

function renderBody() {
  const body = els.body;
  if (!body) return;
  body.replaceChildren();

  const section = SECTIONS.find((s) => s.key === activeSection) || SECTIONS[0];
  body.appendChild(groupTitle(`${section.label} settings`));

  for (const entry of SCHEMA) {
    if (entry.section !== activeSection) continue;
    body.appendChild(field(entry));
  }

  // Main carries two things that are not preferences: a readout and a
  // destructive action. They live at the bottom of the section rather than
  // among the toggles, so a mis-tap while changing a preference is never
  // one row away from wiping the app.
  if (activeSection === 'main') {
    body.appendChild(groupTitle('About'));

    const version = document.createElement('div');
    version.className = 'settings-field';
    const versionLabel = document.createElement('span');
    versionLabel.className = 'settings-field__label';
    versionLabel.textContent = 'App version';
    const versionValue = document.createElement('p');
    versionValue.className = 'settings-readout';
    versionValue.id = 'settingsVersion';
    versionValue.textContent = `Omni 2D ${APP_VERSION}`;
    version.appendChild(versionLabel);
    version.appendChild(versionValue);
    body.appendChild(version);

    const danger = document.createElement('div');
    danger.className = 'settings-field';
    const dangerLabel = document.createElement('span');
    dangerLabel.className = 'settings-field__label';
    dangerLabel.textContent = 'Clear all app data';
    const dangerHint = document.createElement('p');
    dangerHint.className = 'settings-field__hint';
    dangerHint.textContent = 'Removes every project, palette, saved session and setting. This cannot be undone.';
    const dangerBtn = document.createElement('button');
    dangerBtn.type = 'button';
    dangerBtn.className = 'btn btn--danger';
    dangerBtn.id = 'settingsClearBtn';
    dangerBtn.textContent = 'Clear all app data…';
    dangerBtn.addEventListener('click', () => { els.clearModal.hidden = false; });
    danger.appendChild(dangerLabel);
    danger.appendChild(dangerHint);
    danger.appendChild(dangerBtn);
    body.appendChild(danger);
  }
}

function renderTabs() {
  const tabs = els.tabs;
  if (!tabs) return;
  tabs.replaceChildren();
  for (const section of SECTIONS) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'settings-tab';
    button.id = `settingsTab-${section.key}`;
    button.setAttribute('role', 'tab');
    button.setAttribute('aria-selected', String(section.key === activeSection));
    button.textContent = section.label;
    button.addEventListener('click', () => showSection(section.key));
    tabs.appendChild(button);
  }
}

export function showSection(key) {
  if (!SECTIONS.some((s) => s.key === key)) return;
  activeSection = key;
  renderTabs();
  renderBody();
}

export function activeSettingsSection() {
  return activeSection;
}

// `from` is the element to hide on the way in and show again on the way
// out; `onReturn` is anything that screen needs run once it is back.
export function openSettings({ section = 'main', from = null, onReturn = null } = {}) {
  origin = { from, onReturn };
  showSection(section);
  els.clearModal.hidden = true;
  if (from) {
    transitionHidden(from, els.screen);
  } else {
    els.screen.hidden = false;
    playEnter(els.screen);
  }
}

export function closeSettings() {
  const back = origin;
  origin = null;
  const finish = () => { if (back && back.onReturn) back.onReturn(); };
  if (back && back.from) {
    transitionHidden(els.screen, back.from).then(finish);
  } else {
    els.screen.hidden = true;
    finish();
  }
}

export function isSettingsOpen() {
  return Boolean(els.screen) && !els.screen.hidden;
}

export function initSettingsUI({ toast } = {}) {
  if (toast) onToast = toast;
  els.screen = document.getElementById('settingsScreen');
  els.tabs = document.getElementById('settingsTabs');
  els.body = document.getElementById('settingsBody');
  els.back = document.getElementById('settingsBackBtn');
  els.status = document.getElementById('settingsStatus');
  els.clearModal = document.getElementById('settingsClearModal');
  els.clearConfirm = document.getElementById('settingsClearConfirmBtn');
  els.clearCancel = document.getElementById('settingsClearCancelBtn');
  if (!els.screen) return;

  els.back.addEventListener('click', () => closeSettings());
  els.clearCancel.addEventListener('click', () => { els.clearModal.hidden = true; });
  els.clearConfirm.addEventListener('click', async () => {
    els.clearModal.hidden = true;
    try {
      await clearAllData();
      await resetSettings();
      onToast('All app data cleared. Reloading…');
      // A reload rather than trying to reset every module's in-memory
      // state by hand: the stores are empty, but half the app is still
      // holding objects loaded from them, and there is no honest way to
      // put all of that back to first-launch condition in place. Starting
      // the app over is the only state that is genuinely consistent with
      // what was just done to the database.
      setTimeout(() => window.location.reload(), 700);
    } catch (error) {
      console.warn('Clearing app data failed', error);
      onToast('Could not clear app data on this device.');
    }
  });

  // The store is the single source of truth for what the controls show, so
  // a change made anywhere -- including a reset -- re-renders them.
  subscribeSettings((key) => {
    if (!isSettingsOpen()) return;
    // A slider updates its own readout as it is dragged; re-rendering the
    // whole section on every step would tear the input out from under the
    // finger holding it.
    const entry = key ? SCHEMA.find((e) => e.key === key) : null;
    if (entry && entry.kind === 'slider') return;
    renderBody();
  });

  renderTabs();
  renderBody();
}
